package com.npcheatmap;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;

@ConfigGroup("npcheatmap")
public interface NpcHeatmapConfig extends Config
{
	@ConfigItem(
		keyName = "npcNames",
		name = "NPC Names",
		description = "Comma-separated list of NPC names to track (case-insensitive)",
		position = 0
	)
	default String npcNames()
	{
		return "";
	}

	@Range(min = 0, max = 255)
	@ConfigItem(
		keyName = "tileOpacity",
		name = "Tile Opacity",
		description = "Opacity of the heatmap tile fill (0 = transparent, 255 = fully opaque)",
		position = 1
	)
	default int tileOpacity()
	{
		return 127;
	}

	@ConfigItem(
		keyName = "ignoreAttackingNpcs",
		name = "Ignore Attacking NPCs",
		description = "Do not track tile positions of NPCs that are currently attacking the player",
		position = 2
	)
	default boolean ignoreAttackingNpcs()
	{
		return true;
	}

	@ConfigItem(
		keyName = "ignoreDyingNpcs",
		name = "Ignore Dying NPCs",
		description = "Do not track tile positions of NPCs that are currently dying",
		position = 3
	)
	default boolean ignoreDyingNpcs()
	{
		return true;
	}

	@ConfigItem(
		keyName = "trackSouthWestTileOnly",
		name = "Track south-west tile only",
		description = "When enabled, only the south-west tile of an NPC is tracked. When disabled, every tile the NPC occupies is tracked.",
		position = 4
	)
	default boolean trackSouthWestTileOnly()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showTileCount",
		name = "Show tile count",
		description = "Display the tick count above each heatmap tile",
		position = 5
	)
	default boolean showTileCount()
	{
		return false;
	}
}

package com.npcheatmap;

import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

import javax.inject.Inject;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.util.Map;

public class NpcHeatmapMinimapOverlay extends Overlay
{
	private final Client client;
	private final NpcHeatmapPlugin plugin;
	private final NpcHeatmapConfig config;

	@Inject
	NpcHeatmapMinimapOverlay(Client client, NpcHeatmapPlugin plugin, NpcHeatmapConfig config)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setPriority(PRIORITY_LOW);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		Map<String, Map<WorldPoint, Integer>> tileCountsByNpcName = plugin.getTileCountsByNpcName();
		if (tileCountsByNpcName.isEmpty())
		{
			return null;
		}

		for (Map.Entry<String, Map<WorldPoint, Integer>> npcEntry : tileCountsByNpcName.entrySet())
		{
			Map<WorldPoint, Integer> tileCounts = npcEntry.getValue();
			if (tileCounts.isEmpty())
			{
				continue;
			}

			int highestTileCount = tileCounts.values().stream().mapToInt(Integer::intValue).max().orElse(1);

			for (Map.Entry<WorldPoint, Integer> tileEntry : tileCounts.entrySet())
			{
				WorldPoint worldPoint = tileEntry.getKey();
				int tileCount = tileEntry.getValue();

				if (worldPoint.getPlane() != client.getPlane())
				{
					continue;
				}

				if (!isHighestCountForTile(worldPoint, tileCount, npcEntry.getKey(), tileCountsByNpcName))
				{
					continue;
				}

				LocalPoint localPoint = LocalPoint.fromWorld(client, worldPoint);
				if (localPoint == null)
				{
					continue;
				}

				int localX = localPoint.getX() & -Perspective.LOCAL_TILE_SIZE;
				int localY = localPoint.getY() & -Perspective.LOCAL_TILE_SIZE;

				net.runelite.api.Point mp1 = Perspective.localToMinimap(client, new LocalPoint(localX, localY));
				net.runelite.api.Point mp2 = Perspective.localToMinimap(client, new LocalPoint(localX, localY + Perspective.LOCAL_TILE_SIZE));
				net.runelite.api.Point mp3 = Perspective.localToMinimap(client, new LocalPoint(localX + Perspective.LOCAL_TILE_SIZE, localY + Perspective.LOCAL_TILE_SIZE));
				net.runelite.api.Point mp4 = Perspective.localToMinimap(client, new LocalPoint(localX + Perspective.LOCAL_TILE_SIZE, localY));

				if (mp1 == null || mp2 == null || mp3 == null || mp4 == null)
				{
					continue;
				}

				Polygon minimapTilePoly = new Polygon();
				minimapTilePoly.addPoint(mp1.getX(), mp1.getY());
				minimapTilePoly.addPoint(mp2.getX(), mp2.getY());
				minimapTilePoly.addPoint(mp3.getX(), mp3.getY());
				minimapTilePoly.addPoint(mp4.getX(), mp4.getY());

				float heatRatio = (float) tileCount / highestTileCount;
				Color tileColor = heatRatioToColor(heatRatio, config.tileOpacity());

				graphics.setColor(tileColor);
				graphics.fillPolygon(minimapTilePoly);
			}
		}

		return null;
	}

	private boolean isHighestCountForTile(
		WorldPoint worldPoint,
		int countForCurrentNpc,
		String currentNpcName,
		Map<String, Map<WorldPoint, Integer>> tileCountsByNpcName
	) {
		for (Map.Entry<String, Map<WorldPoint, Integer>> npcEntry : tileCountsByNpcName.entrySet())
		{
			if (npcEntry.getKey().equals(currentNpcName))
			{
				continue;
			}

			Integer otherNpcCount = npcEntry.getValue().get(worldPoint);
			if (otherNpcCount != null && otherNpcCount > countForCurrentNpc)
			{
				return false;
			}
		}

		return true;
	}

	private Color heatRatioToColor(float heatRatio, int alpha)
	{
		int red;
		int green;

		if (heatRatio <= 0.5f)
		{
			red = Math.round(heatRatio * 2f * 255f);
			green = 255;
		}
		else
		{
			red = 255;
			green = Math.round((1f - (heatRatio - 0.5f) * 2f) * 255f);
		}

		red = Math.max(0, Math.min(255, red));
		green = Math.max(0, Math.min(255, green));

		return new Color(red, green, 0, alpha);
	}
}

package com.npcheatmap;

import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

import javax.inject.Inject;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Polygon;
import java.util.HashMap;
import java.util.Map;

public class NpcHeatmapOverlay extends Overlay
{
	private final Client client;
	private final NpcHeatmapPlugin plugin;
	private final NpcHeatmapConfig config;

	@Inject
	NpcHeatmapOverlay(Client client, NpcHeatmapPlugin plugin, NpcHeatmapConfig config)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		Map<String, Map<WorldPoint, Integer>> tileCountsByNpcName = plugin.getTileCountsByNpcName();
		if (tileCountsByNpcName.isEmpty())
		{
			return null;
		}

		int opacity = config.tileOpacity();

		for (Map.Entry<String, Map<WorldPoint, Integer>> npcEntry : tileCountsByNpcName.entrySet())
		{
			Map<WorldPoint, Integer> tileCounts = npcEntry.getValue();
			if (tileCounts.isEmpty())
			{
				continue;
			}

			int highestTileCount = tileCounts.values().stream().mapToInt(Integer::intValue).max().orElse(1);

			for (Map.Entry<WorldPoint, Integer> tileEntry : tileCounts.entrySet())
			{
				WorldPoint worldPoint = tileEntry.getKey();
				int tileCount = tileEntry.getValue();

				if (worldPoint.getPlane() != client.getPlane())
				{
					continue;
				}

				if (!isHighestCountForTile(worldPoint, tileCount, npcEntry.getKey(), tileCountsByNpcName))
				{
					continue;
				}

				LocalPoint localPoint = LocalPoint.fromWorld(client, worldPoint);
				if (localPoint == null)
				{
					continue;
				}

				Polygon tilePoly = Perspective.getCanvasTilePoly(client, localPoint);
				if (tilePoly == null)
				{
					continue;
				}

				float heatRatio = (float) tileCount / highestTileCount;
				Color tileColor = heatRatioToColor(heatRatio, opacity);

				graphics.setColor(tileColor);
				graphics.fillPolygon(tilePoly);

				if (config.showTileCount())
				{
					drawTileCount(graphics, tilePoly, tileCount);
				}
			}
		}

		return null;
	}

	private void drawTileCount(Graphics2D graphics, Polygon tilePoly, int tileCount)
	{
		String countText = String.valueOf(tileCount);
		FontMetrics fontMetrics = graphics.getFontMetrics();
		int textWidth = fontMetrics.stringWidth(countText);
		int textHeight = fontMetrics.getAscent();

		int centerX = (int) tilePoly.getBounds().getCenterX() - textWidth / 2;
		int centerY = (int) tilePoly.getBounds().getCenterY() + textHeight / 2;

		graphics.setColor(Color.BLACK);
		graphics.drawString(countText, centerX + 1, centerY + 1);

		graphics.setColor(Color.WHITE);
		graphics.drawString(countText, centerX, centerY);
	}

	private boolean isHighestCountForTile(
		WorldPoint worldPoint,
		int countForCurrentNpc,
		String currentNpcName,
		Map<String, Map<WorldPoint, Integer>> tileCountsByNpcName
	) {
		for (Map.Entry<String, Map<WorldPoint, Integer>> npcEntry : tileCountsByNpcName.entrySet())
		{
			if (npcEntry.getKey().equals(currentNpcName))
			{
				continue;
			}

			Integer otherNpcCount = npcEntry.getValue().get(worldPoint);
			if (otherNpcCount != null && otherNpcCount > countForCurrentNpc)
			{
				return false;
			}
		}

		return true;
	}

	private Color heatRatioToColor(float heatRatio, int alpha)
	{
		int red;
		int green;

		if (heatRatio <= 0.5f)
		{
			red = Math.round(heatRatio * 2f * 255f);
			green = 255;
		}
		else
		{
			red = 255;
			green = Math.round((1f - (heatRatio - 0.5f) * 2f) * 255f);
		}

		red = Math.max(0, Math.min(255, red));
		green = Math.max(0, Math.min(255, green));

		return new Color(red, green, 0, alpha);
	}
